CREATE OR REPLACE FUNCTION ops.complete_raw_capture_event(p_event_pk uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event ops.events%rowtype;
  v_route jsonb;
begin
  select * into v_event from ops.events where event_pk=p_event_pk for update;
  if not found then return jsonb_build_object('ok',false,'reason','EVENT_NOT_FOUND'); end if;
  if v_event.event_type<>'channel.raw.received' then return jsonb_build_object('ok',false,'reason','NOT_RAW_CAPTURE_EVENT'); end if;
  begin
    v_route:=ops.route_line_raw_event_v1(p_event_pk);
  exception when others then
    v_route:=jsonb_build_object('routed',false,'reason','DOWNSTREAM_ROUTE_ERROR','error',left(sqlerrm,500));
    update ops.raw_inputs set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('line_ingestion_route_error',left(sqlerrm,500),'line_ingestion_route_error_at',now()),updated_at=now() where raw_input_id=v_event.raw_input_id;
  end;
  if v_event.processing_state not in ('COMPLETED'::ops.event_processing_state,'CANCELLED'::ops.event_processing_state) then
    update ops.events set processing_state='COMPLETED'::ops.event_processing_state,updated_at=now() where event_pk=p_event_pk;
  end if;
  return jsonb_build_object('ok',true,'event_pk',p_event_pk,'processing_state','COMPLETED','downstream_route',v_route);
end;
$function$

CREATE OR REPLACE FUNCTION ops.ingest_material_event(p_raw_input_id text, p_schema_version text, p_source_system text, p_channel text, p_event_id text, p_idempotency_key text, p_trace_id text, p_event_type text, p_occurred_at timestamp with time zone, p_sender_type text, p_content_type text, p_original_ref text, p_sender_ref text DEFAULT NULL::text, p_source_account_ref text DEFAULT NULL::text, p_thread_id text DEFAULT NULL::text, p_message_id text DEFAULT NULL::text, p_raw_summary text DEFAULT NULL::text, p_entity_type_hint text DEFAULT NULL::text, p_entity_id_if_known text DEFAULT NULL::text, p_ai_parsed boolean DEFAULT false, p_ai_confidence numeric DEFAULT NULL::numeric, p_sensitive boolean DEFAULT false, p_consent_signal text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_correlation_id text DEFAULT NULL::text, p_causation_event_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_route ops.routing_rules;
  v_event ops.events;
  v_existing_raw ops.raw_inputs;
  v_duplicate_event boolean := false;
begin
  if p_raw_input_id is null or btrim(p_raw_input_id) = '' then
    raise exception 'raw_input_id is required for material ingestion';
  end if;
  if p_source_system is null or btrim(p_source_system) = '' then
    raise exception 'source_system is required';
  end if;
  if p_event_id is null or btrim(p_event_id) = '' then
    raise exception 'event_id is required';
  end if;
  if p_idempotency_key is null or btrim(p_idempotency_key) = '' then
    raise exception 'idempotency_key is required';
  end if;
  if p_trace_id is null or btrim(p_trace_id) = '' then
    raise exception 'trace_id is required';
  end if;
  if p_original_ref is null or btrim(p_original_ref) = '' then
    raise exception 'original_ref is required for provenance';
  end if;

  select * into v_route
  from ops.routing_rules
  where event_type = p_event_type and active = true;

  if not found then
    raise exception 'unsupported or inactive event_type: %', p_event_type;
  end if;

  if v_route.material is false then
    raise exception 'event_type % is non-material; use a non-material event path', p_event_type;
  end if;

  select * into v_existing_raw
  from ops.raw_inputs
  where source_system = p_source_system
    and coalesce(source_account_ref, '') = coalesce(p_source_account_ref, '')
    and original_ref = p_original_ref
  limit 1;

  if found and v_existing_raw.raw_input_id <> p_raw_input_id then
    raise exception 'source provenance already bound to raw_input_id %', v_existing_raw.raw_input_id;
  end if;

  insert into ops.raw_inputs (
    raw_input_id, received_at, source_system, channel, source_account_ref,
    thread_id, message_id, sender_type, sender_ref, content_type, original_ref,
    raw_summary, natural_language_summary, classification, entity_type_hint,
    entity_id_if_known, ai_parsed, ai_confidence, processing_status, sensitive,
    consent_signal, metadata
  ) values (
    p_raw_input_id, now(), p_source_system, p_channel, p_source_account_ref,
    p_thread_id, p_message_id, p_sender_type, p_sender_ref, p_content_type, p_original_ref,
    p_raw_summary, p_raw_summary, p_event_type, p_entity_type_hint,
    p_entity_id_if_known, p_ai_parsed, p_ai_confidence, 'RAW_STORED', p_sensitive,
    p_consent_signal, coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (raw_input_id) do nothing;

  select exists(
    select 1 from ops.events
    where (source_system = p_source_system and event_id = p_event_id)
       or idempotency_key = p_idempotency_key
  ) into v_duplicate_event;

  v_event := ops.register_event(
    p_schema_version,
    p_source_system,
    p_event_id,
    p_idempotency_key,
    p_trace_id,
    p_event_type,
    p_occurred_at,
    p_raw_input_id,
    p_correlation_id,
    p_causation_event_id
  );

  return jsonb_build_object(
    'raw_input_id', p_raw_input_id,
    'event_pk', v_event.event_pk,
    'event_id', v_event.event_id,
    'processing_state', v_event.processing_state,
    'duplicate_event', v_duplicate_event,
    'route_key', v_route.route_key,
    'domain', v_route.domain,
    'evidence_expected', v_route.evidence_expected,
    'approval_policy', v_route.approval_policy
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.line_capture_enrich_context(p_raw_input_id text, p_source_account_ref text, p_occurred_at timestamp with time zone, p_identity_ref text DEFAULT NULL::text, p_identity_type text DEFAULT 'USER'::text, p_identity_display_name text DEFAULT NULL::text, p_identity_picture_url text DEFAULT NULL::text, p_identity_status_message text DEFAULT NULL::text, p_identity_language text DEFAULT NULL::text, p_thread_ref text DEFAULT NULL::text, p_thread_type text DEFAULT NULL::text, p_thread_display_name text DEFAULT NULL::text, p_thread_picture_url text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_raw ops.raw_inputs%rowtype;
  v_meta jsonb := coalesce(p_metadata,'{}'::jsonb);
begin
  if p_source_account_ref not in ('LINE_OA:MEYOU_CONNECT_OFFICIAL','LINE_OA:MYC_DATA_BOT') then
    raise exception 'LINE source account not allowed';
  end if;

  select * into v_raw from ops.raw_inputs where raw_input_id = p_raw_input_id;
  if not found or v_raw.source_system <> 'LINE' or v_raw.source_account_ref <> p_source_account_ref then
    raise exception 'LINE raw input not found or account mismatch';
  end if;

  if p_identity_ref is not null then
    insert into ops.channel_identities(
      source_system,source_account_ref,identity_ref,identity_type,display_name,picture_url,status_message,language,
      first_seen_at,last_seen_at,metadata
    ) values (
      'LINE',p_source_account_ref,p_identity_ref,coalesce(p_identity_type,'USER'),p_identity_display_name,p_identity_picture_url,
      p_identity_status_message,p_identity_language,p_occurred_at,p_occurred_at,v_meta
    )
    on conflict(source_system,source_account_ref,identity_ref) do update set
      identity_type = excluded.identity_type,
      display_name = coalesce(excluded.display_name,ops.channel_identities.display_name),
      picture_url = coalesce(excluded.picture_url,ops.channel_identities.picture_url),
      status_message = coalesce(excluded.status_message,ops.channel_identities.status_message),
      language = coalesce(excluded.language,ops.channel_identities.language),
      last_seen_at = greatest(ops.channel_identities.last_seen_at,excluded.last_seen_at),
      metadata = ops.channel_identities.metadata || excluded.metadata,
      updated_at = now();
  end if;

  if p_thread_ref is not null then
    insert into ops.channel_threads(
      source_system,source_account_ref,thread_ref,thread_type,display_name,picture_url,first_seen_at,last_seen_at,metadata
    ) values (
      'LINE',p_source_account_ref,p_thread_ref,coalesce(p_thread_type,'UNKNOWN'),p_thread_display_name,p_thread_picture_url,
      p_occurred_at,p_occurred_at,v_meta
    )
    on conflict(source_system,source_account_ref,thread_ref) do update set
      thread_type = excluded.thread_type,
      display_name = coalesce(excluded.display_name,ops.channel_threads.display_name),
      picture_url = coalesce(excluded.picture_url,ops.channel_threads.picture_url),
      last_seen_at = greatest(ops.channel_threads.last_seen_at,excluded.last_seen_at),
      metadata = ops.channel_threads.metadata || excluded.metadata,
      updated_at = now();
  end if;

  update ops.raw_inputs
  set metadata = coalesce(metadata,'{}'::jsonb)
      || v_meta
      || case when p_identity_display_name is not null then jsonb_build_object('sender_display_name',p_identity_display_name) else '{}'::jsonb end
      || case when p_thread_display_name is not null then jsonb_build_object('thread_display_name',p_thread_display_name) else '{}'::jsonb end,
      updated_at = now()
  where raw_input_id = p_raw_input_id;

  return jsonb_build_object('ok',true,'raw_input_id',p_raw_input_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.line_capture_ingest(p_endpoint_key text, p_request_id text, p_request_timestamp timestamp with time zone, p_payload_bytes integer, p_replay_key_hash text, p_client_key_hash text, p_event_envelope jsonb, p_security_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_complete jsonb;
  v_envelope jsonb := coalesce(p_event_envelope,'{}'::jsonb);
  v_source_account_ref text;
  v_provider_event_id text;
  v_raw_id text;
  v_alloc jsonb;
begin
  if p_endpoint_key not in ('line_official_webhook_test','line_group_bot_webhook_test') then
    return jsonb_build_object('decision','DENY','reason_code','LINE_ENDPOINT_NOT_ALLOWED');
  end if;

  v_source_account_ref := v_envelope->>'source_account_ref';
  v_provider_event_id := v_envelope->>'event_id';
  if v_source_account_ref not in ('LINE_OA:MEYOU_CONNECT_OFFICIAL','LINE_OA:MYC_DATA_BOT') then
    return jsonb_build_object('decision','DENY','reason_code','LINE_SOURCE_ACCOUNT_NOT_ALLOWED');
  end if;
  if v_provider_event_id is null or btrim(v_provider_event_id)='' then
    return jsonb_build_object('decision','DENY','reason_code','LINE_PROVIDER_EVENT_ID_REQUIRED');
  end if;

  perform pg_advisory_xact_lock(hashtextextended('LINE_RAW|'||v_source_account_ref||'|'||v_provider_event_id,0));

  select raw_input_id into v_raw_id
  from ops.channel_event_raw_map
  where source_system='LINE' and source_account_ref=v_source_account_ref and provider_event_id=v_provider_event_id;

  if v_raw_id is null then
    v_alloc := config.allocate_business_id('Raw Input','LINE_CAPTURE',jsonb_build_object('source_system','LINE','source_account_ref',v_source_account_ref,'provider_event_id',v_provider_event_id));
    v_raw_id := v_alloc->>'allocated_id';
  end if;

  v_envelope := v_envelope || jsonb_build_object('raw_input_id',v_raw_id);

  v_result := ops.secure_ingest_material_event(
    p_endpoint_key,
    p_request_id,
    p_request_timestamp,
    p_payload_bytes,
    'application/json',
    true,
    true,
    p_replay_key_hash,
    p_client_key_hash,
    v_envelope,
    coalesce(p_security_metadata,'{}'::jsonb),
    now()
  );

  if coalesce(v_result->>'decision','DENY') = 'ALLOW' and v_result->>'raw_input_id' is not null then
    insert into ops.channel_event_raw_map(source_system,source_account_ref,provider_event_id,raw_input_id)
    values('LINE',v_source_account_ref,v_provider_event_id,v_result->>'raw_input_id')
    on conflict(source_system,source_account_ref,provider_event_id) do nothing;
  end if;

  if coalesce(v_result->>'decision','DENY') = 'ALLOW' and v_result->>'event_pk' is not null then
    v_complete := ops.complete_raw_capture_event((v_result->>'event_pk')::uuid);
    v_result := v_result || jsonb_build_object('capture_completion',v_complete);
  end if;

  return v_result || jsonb_build_object('raw_input_id',v_raw_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.line_capture_register_file(p_raw_input_id text, p_source_account_ref text, p_provider_file_ref text, p_original_filename text, p_content_type text, p_size_bytes bigint, p_checksum_sha256 text, p_mirror_status text, p_sensitive boolean, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_raw ops.raw_inputs%rowtype;
  v_existing ops.file_intake%rowtype;
  v_result jsonb;
begin
  if p_source_account_ref not in ('LINE_OA:MEYOU_CONNECT_OFFICIAL','LINE_OA:MYC_DATA_BOT') then
    raise exception 'LINE source account not allowed';
  end if;
  if p_mirror_status not in ('SOURCE_ONLY','MIRRORED','SOURCE_NOT_MIRRORED','FAILED') then
    raise exception 'invalid mirror status';
  end if;

  select * into v_raw from ops.raw_inputs where raw_input_id = p_raw_input_id;
  if not found or v_raw.source_system <> 'LINE' or v_raw.source_account_ref <> p_source_account_ref then
    raise exception 'LINE raw input not found or account mismatch';
  end if;

  select * into v_existing from ops.file_intake
  where source_system='LINE'
    and coalesce(source_account_ref,'')=coalesce(p_source_account_ref,'')
    and provider_file_ref=p_provider_file_ref
  order by created_at
  limit 1;

  if found then
    update ops.file_intake
    set original_filename = coalesce(p_original_filename,original_filename),
        content_type = coalesce(p_content_type,content_type),
        size_bytes = coalesce(p_size_bytes,size_bytes),
        checksum_sha256 = coalesce(p_checksum_sha256,checksum_sha256),
        mirror_status = p_mirror_status,
        sensitive = coalesce(p_sensitive,sensitive),
        metadata = metadata || coalesce(p_metadata,'{}'::jsonb),
        updated_at = now()
    where file_intake_pk=v_existing.file_intake_pk;
    v_result := jsonb_build_object('file_intake_pk',v_existing.file_intake_pk,'duplicate_file',true,'mirror_status',p_mirror_status);
  else
    v_result := ops.register_file_intake(
      p_raw_input_id,'LINE',p_provider_file_ref,p_source_account_ref,p_original_filename,p_content_type,p_size_bytes,
      p_checksum_sha256,p_mirror_status,p_sensitive,coalesce(p_metadata,'{}'::jsonb)
    );
  end if;

  update ops.raw_inputs
  set metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('attachment',coalesce(p_metadata,'{}'::jsonb)),
      updated_at = now()
  where raw_input_id=p_raw_input_id;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION ops.register_event(p_schema_version text, p_source_system text, p_event_id text, p_idempotency_key text, p_trace_id text, p_event_type text, p_occurred_at timestamp with time zone, p_raw_input_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_causation_event_id text DEFAULT NULL::text)
 RETURNS ops.events
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_event ops.events;
begin
  select * into v_event from ops.events where source_system = p_source_system and event_id = p_event_id;
  if found then return v_event; end if;
  select * into v_event from ops.events where idempotency_key = p_idempotency_key;
  if found then return v_event; end if;
  insert into ops.events (
    schema_version, source_system, event_id, idempotency_key, trace_id,
    correlation_id, causation_event_id, event_type, occurred_at, raw_input_id, processing_state
  ) values (
    p_schema_version, p_source_system, p_event_id, p_idempotency_key, p_trace_id,
    p_correlation_id, p_causation_event_id, p_event_type, p_occurred_at, p_raw_input_id,
    case when p_raw_input_id is null then 'RECEIVED'::ops.event_processing_state else 'RAW_STORED'::ops.event_processing_state end
  ) returning * into v_event;
  return v_event;
exception
  when unique_violation then
    select * into v_event from ops.events
    where (source_system = p_source_system and event_id = p_event_id) or idempotency_key = p_idempotency_key
    order by created_at limit 1;
    if found then return v_event; end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION ops.route_line_raw_event_v1(p_event_pk uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event ops.events;
  v_raw ops.raw_inputs;
  v_parse jsonb;
  v_child ops.events;
  v_effect_key text;
begin
  select * into v_event from ops.events where event_pk=p_event_pk;
  if not found then raise exception 'EVENT_NOT_FOUND'; end if;
  if v_event.event_type<>'channel.raw.received' or v_event.source_system<>'LINE' then return jsonb_build_object('routed',false,'reason','NOT_LINE_RAW_EVENT'); end if;
  select * into v_raw from ops.raw_inputs where raw_input_id=v_event.raw_input_id;
  if not found then raise exception 'RAW_INPUT_NOT_FOUND'; end if;

  v_effect_key:='line_ingestion_classification|'||v_raw.raw_input_id;
  if exists(select 1 from ops.event_effects where effect_key=v_effect_key) then
    select coalesce(v_raw.metadata->'line_ingestion','{}'::jsonb) into v_parse;
    return jsonb_build_object('routed',true,'duplicate',true,'raw_input_id',v_raw.raw_input_id,'parse',v_parse);
  end if;

  v_parse:=ops.parse_line_candidate_raw_v1(v_raw.raw_input_id);
  update ops.raw_inputs set
    classification=v_parse->>'classification',
    entity_type=case when v_parse->>'classification'='CANDIDATE_LEAD' then 'CandidateLead' else entity_type end,
    ai_parsed=true,
    ai_confidence=nullif(v_parse->>'confidence','')::numeric,
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('line_ingestion',v_parse,'line_ingestion_routed_at',now()),
    updated_at=now()
  where raw_input_id=v_raw.raw_input_id;

  if v_parse->>'classification'='CANDIDATE_LEAD' then
    v_child:=ops.register_event(
      v_event.schema_version,'LINE','DERIVED:CANDIDATE_LEAD:'||v_raw.raw_input_id,
      encode(extensions.digest('candidate.lead.received|'||v_raw.raw_input_id,'sha256'),'hex'),v_event.trace_id,
      'candidate.lead.received',v_event.occurred_at,v_raw.raw_input_id,v_event.correlation_id,v_event.event_id
    );
    perform ops.register_effect(v_event.event_pk,'line_ingestion_classification',v_effect_key,'CandidateLead',null,'ops.events:'||v_child.event_pk::text);
    return jsonb_build_object('routed',true,'duplicate',false,'raw_input_id',v_raw.raw_input_id,'classification','CANDIDATE_LEAD','child_event_pk',v_child.event_pk,'child_event_id',v_child.event_id,'parse',v_parse);
  else
    perform ops.register_effect(v_event.event_pk,'line_ingestion_classification',v_effect_key,'RawInput',v_raw.raw_input_id,'classification:'||(v_parse->>'classification'));
    return jsonb_build_object('routed',true,'duplicate',false,'raw_input_id',v_raw.raw_input_id,'classification',v_parse->>'classification','parse',v_parse);
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION ops.apply_failure_transition(p_event_pk uuid, p_worker_key text, p_error_class text, p_error_message text DEFAULT NULL::text, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event ops.events;
  v_worker ops.worker_registry;
  v_class text := upper(coalesce(nullif(btrim(p_error_class),''),'UNKNOWN'));
  v_new_attempt integer;
  v_state ops.event_processing_state;
  v_retry_at timestamptz;
begin
  select * into v_event from ops.events where event_pk = p_event_pk for update;
  if not found then raise exception 'unknown event_pk: %', p_event_pk; end if;

  select * into v_worker from ops.worker_registry where worker_key = p_worker_key;
  if not found then raise exception 'unknown worker_key: %', p_worker_key; end if;

  v_new_attempt := v_event.processing_attempt + 1;
  v_retry_at := null;

  if v_class = 'TRANSIENT' then
    if v_event.processing_attempt < v_worker.max_retries then
      v_state := 'RETRY_WAIT';
      v_retry_at := p_now + ops.retry_delay_for_attempt(v_new_attempt);
    else
      v_state := 'DEAD_LETTER';
    end if;
  elsif v_class in ('VALIDATION','AUTH') then
    v_state := 'NEEDS_REVIEW';
  elsif v_class = 'CONFLICT' then
    v_state := 'DQ_HOLD';
  elsif v_class = 'PRIVACY' then
    v_state := 'REJECTED';
  elsif v_class = 'BUSINESS_RULE' then
    v_state := 'APPROVAL_REQUIRED';
  else
    v_state := 'NEEDS_REVIEW';
  end if;

  update ops.events
  set processing_attempt = v_new_attempt,
      processing_state = v_state,
      next_retry_at = v_retry_at,
      last_error_class = v_class,
      last_error_message = left(p_error_message, 2000),
      updated_at = now()
  where event_pk = p_event_pk;

  if v_state = 'DEAD_LETTER' then
    insert into ops.dead_letters(event_pk, error_class, error_message, failed_at)
    values (p_event_pk, v_class, left(p_error_message,2000), p_now)
    on conflict (event_pk) do update set
      error_class = excluded.error_class,
      error_message = excluded.error_message,
      failed_at = excluded.failed_at,
      replay_status = 'PENDING',
      reviewed_by = null,
      reviewed_at = null;
  end if;

  return jsonb_build_object(
    'event_pk', p_event_pk,
    'processing_state', v_state,
    'processing_attempt', v_new_attempt,
    'next_retry_at', v_retry_at,
    'error_class', v_class
  );
end;
$function$

CREATE OR REPLACE FUNCTION ops.parse_line_candidate_raw_base_v1(p_raw_input_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_raw ops.raw_inputs;
  v_text text;
  v_lines text[];
  v_line text;
  v_name text;
  v_phone text;
  v_dob date;
  v_m text[];
  v_day int;
  v_month int;
  v_year int;
  v_mon text;
  v_education text;
  v_age int;
  v_weight int;
  v_height int;
  v_origin text;
  v_tattoo boolean;
  v_job_id text;
  v_partner_id text;
  v_classification text := 'CONTEXT_OR_OTHER';
  v_missing jsonb := '[]'::jsonb;
  v_conf numeric := 0;
  v_numeric_lines int[] := '{}';
  v_n int;
  v_dedupe_key text;
begin
  select * into v_raw from ops.raw_inputs where raw_input_id=p_raw_input_id;
  if not found then raise exception 'RAW_INPUT_NOT_FOUND:%',p_raw_input_id; end if;

  v_text:=coalesce(v_raw.raw_summary,'');
  if v_raw.source_system<>'LINE' then
    return jsonb_build_object('classification','NOT_LINE','raw_input_id',p_raw_input_id,'confidence',100,'missing_fields','[]'::jsonb,'parser_version','line_candidate_v1');
  end if;
  if v_raw.content_type='LINE_IMAGE' then
    return jsonb_build_object('classification','EVIDENCE_IMAGE','raw_input_id',p_raw_input_id,'confidence',100,'missing_fields',jsonb_build_array('candidate_relation'),'parser_version','line_candidate_v1');
  end if;
  if v_raw.content_type<>'LINE_TEXT' then
    return jsonb_build_object('classification','UNSUPPORTED_CONTENT','raw_input_id',p_raw_input_id,'confidence',100,'missing_fields','[]'::jsonb,'parser_version','line_candidate_v1');
  end if;
  if v_text ~* 'MYC-(OFFICIAL|GROUP)-FINAL-[0-9]+' or v_text ilike '%bot ใช้ได้แล้ว%' or v_text ilike '%เทส%' then
    return jsonb_build_object('classification','TEST_CONTROL','raw_input_id',p_raw_input_id,'confidence',100,'missing_fields','[]'::jsonb,'parser_version','line_candidate_v1');
  end if;

  v_lines:=regexp_split_to_array(replace(v_text,E'\r',''),E'\n');
  foreach v_line in array v_lines loop
    v_line:=btrim(v_line);
    if v_line='' then continue; end if;

    if v_phone is null then
      v_m:=regexp_match(v_line,'(0[0-9]{2}[- ]?[0-9]{3}[- ]?[0-9]{4})');
      if v_m is not null then
        v_phone:=regexp_replace(v_m[1],'[^0-9]','','g');
        if length(v_phone)<>10 then v_phone:=null; end if;
      end if;
    end if;

    if v_dob is null then
      v_m:=regexp_match(v_line,'([0-9]{1,2})/([0-9]{1,2})/([0-9]{4})');
      if v_m is not null then
        v_day:=v_m[1]::int; v_month:=v_m[2]::int; v_year:=v_m[3]::int;
        if v_year>=2400 then v_year:=v_year-543; end if;
        begin v_dob:=make_date(v_year,v_month,v_day); exception when others then v_dob:=null; end;
      else
        v_m:=regexp_match(v_line,'([0-9]{1,2})\s*(ม\.ค\.?|ก\.พ\.?|มี\.ค\.?|เม\.ย\.?|พ\.ค\.?|มิ\.ย\.?|ก\.ค\.?|ส\.ค\.?|ก\.ย\.?|ต\.ค\.?|พ\.ย\.?|ธ\.ค\.?)\s*([0-9]{4})');
        if v_m is not null then
          v_day:=v_m[1]::int; v_mon:=v_m[2]; v_year:=v_m[3]::int;
          if v_year>=2400 then v_year:=v_year-543; end if;
          v_month:=case when v_mon like 'ม.ค%' then 1 when v_mon like 'ก.พ%' then 2 when v_mon like 'มี.ค%' then 3 when v_mon like 'เม.ย%' then 4 when v_mon like 'พ.ค%' then 5 when v_mon like 'มิ.ย%' then 6 when v_mon like 'ก.ค%' then 7 when v_mon like 'ส.ค%' then 8 when v_mon like 'ก.ย%' then 9 when v_mon like 'ต.ค%' then 10 when v_mon like 'พ.ย%' then 11 when v_mon like 'ธ.ค%' then 12 end;
          begin v_dob:=make_date(v_year,v_month,v_day); exception when others then v_dob:=null; end;
        end if;
      end if;
    end if;

    if v_education is null and v_line ~* 'วุฒิ' then
      v_education:=nullif(btrim(regexp_replace(v_line,'^.*วุฒิ(การศึกษา)?\s*[:：]?\s*','','i')),'');
    end if;
    if v_age is null then
      v_m:=regexp_match(v_line,'อายุ\s*[:：]?\s*([0-9]{1,2})');
      if v_m is not null then v_age:=v_m[1]::int; end if;
    end if;
    if v_weight is null then
      v_m:=regexp_match(v_line,'(?:น้ำหนัก|น\.น)\s*[:：]?\s*([0-9]{2,3})','i');
      if v_m is not null then v_weight:=v_m[1]::int; end if;
    end if;
    if v_height is null then
      v_m:=regexp_match(v_line,'(?:ส่วนสูง|สูง|ส\.ส)\s*[:：]?\s*([0-9]{2,3})','i');
      if v_m is not null then v_height:=v_m[1]::int; end if;
    end if;
    if v_origin is null and v_line ~ 'มาจาก' then
      v_origin:=nullif(btrim(regexp_replace(v_line,'^.*มาจาก\s*','','i')),'');
    end if;
    if v_line ~ 'รอยสัก|ลอยสัก' then
      if v_line ~ 'ไม่มี' then v_tattoo:=false; elsif v_line ~ 'มี' then v_tattoo:=true; end if;
    end if;
    if v_line ~ '^[0-9]{2,3}$' then
      v_numeric_lines:=array_append(v_numeric_lines,v_line::int);
    end if;

    if v_name is null then
      if v_line ~ '^สมัครเน็กซ์แคนรอบวันจันทร์' then
        v_name:=nullif(btrim(regexp_replace(v_line,'^สมัครเน็กซ์แคนรอบวันจันทร์\s*','','i')),'');
      elsif v_line ~ '[ก-๙]+\s+[ก-๙]+' and v_line !~ 'สมัคร|เน็กซ์|วุฒิ|น้ำหนัก|ส่วนสูง|อายุ|เบอร์|โทร|รอยสัก|ลอยสัก|มาจาก|วันเดือนปีเกิด' then
        v_name:=v_line;
      end if;
      if v_name is not null then
        v_name:=btrim(regexp_replace(v_name,'^(นางสาว|นาง|นาย|น\.ส\.)\s*','','i'));
      end if;
    end if;
  end loop;

  if v_name is null then
    v_m:=regexp_match(v_text,'^([ก-๙]+[[:space:]]+[ก-๙]+)[[:space:]]+(โรงงาน|สมัคร)','i');
    if v_m is not null then v_name:=ops.normalize_candidate_full_name(v_m[1]); end if;
  end if;

  if v_weight is null and cardinality(v_numeric_lines)>=1 then v_weight:=v_numeric_lines[1]; end if;
  if v_height is null and cardinality(v_numeric_lines)>=2 then v_height:=v_numeric_lines[2]; end if;

  if v_text ~* '(อินนาบะ|อินาบะ|อินนาละ|ออนนาบะ|inaba|ซับ[[:space:]]*[:：-]?[[:space:]]*N&K)' then v_job_id:='MYC-J-000017'; elsif v_text ilike '%เน็กซ์แคน%' or v_text ilike '%next can%' then v_job_id:='MYC-J-000013'; end if;
  if v_text ~* '(ทีมมีน|ทีมมัน|มาจากมีน|จากมีน|พี่มีน)' or v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?มีน([[:space:]]|$)' then
    v_partner_id:=null;
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?มิ้นท์?' or v_text ~* 'แนะนำ[[:space:]]*(คุณ|พี่)?มิ้นท์?' then
    v_partner_id:='MYC-P-0001';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?อีฟ' then
    v_partner_id:='MYC-P-0002';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?หยก' then
    v_partner_id:='MYC-P-0003';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?แพร' then
    v_partner_id:='MYC-P-0004';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?เจน' then
    v_partner_id:='MYC-P-0005';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?เจด้า' then
    v_partner_id:='MYC-P-0006';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?คิม' then
    v_partner_id:='MYC-P-0007';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?เบส' then
    v_partner_id:='MYC-P-0008';
  elsif v_text ~* '(ผู้แนะนำ|ผู้แนะนํา|ผู้เเนะนำ|ผู้แนะนํ|ผุ้แนะนำ|ผุแนะนำ)[[:space:]]*[:：-]?[[:space:]]*(คุณ|พี่)?ไวน์' then
    v_partner_id:='MYC-P-0009';
  elsif v_raw.sender_ref='LINE_USER_ID_FIXTURE_01' and v_text !~* '(ทีมมีน|ทีมมัน|มาจากมีน|จากมีน|พี่มีน)' then
    v_partner_id:='MYC-P-0001';
  elsif v_raw.sender_ref='LINE_USER_ID_FIXTURE_02' then
    v_partner_id:='MYC-P-0002';
  elsif v_raw.sender_ref='LINE_USER_ID_FIXTURE_03' then
    v_partner_id:='MYC-P-0003';
  elsif v_raw.sender_ref='LINE_USER_ID_FIXTURE_04' then
    v_partner_id:='MYC-P-0008';
  end if;

  if v_phone is not null and v_name is not null and v_job_id is not null and (v_dob is not null or v_education is not null or v_age is not null) then
    v_classification:='CANDIDATE_LEAD';
  end if;

  if v_classification='CANDIDATE_LEAD' then
    if v_name is null then v_missing:=v_missing||jsonb_build_array('full_name'); end if;
    if v_phone is null then v_missing:=v_missing||jsonb_build_array('phone'); end if;
    if v_dob is null then v_missing:=v_missing||jsonb_build_array('date_of_birth'); end if;
    if v_education is null then v_missing:=v_missing||jsonb_build_array('education'); end if;
    if v_origin is null then v_missing:=v_missing||jsonb_build_array('origin_area'); end if;
    v_missing:=v_missing||jsonb_build_array('ready_date');
    v_conf:=case when v_name is not null and v_phone is not null and v_dob is not null and v_education is not null and v_partner_id is not null and v_job_id is not null then case when v_origin is null then 96 else 98 end else 90 end;
    v_dedupe_key:=encode(extensions.digest(lower(regexp_replace(coalesce(v_name,''),'\s+','','g'))||'|'||coalesce(v_phone,'')||'|'||coalesce(v_dob::text,''),'sha256'),'hex');
  else
    v_conf:=case when v_classification in ('TEST_CONTROL','EVIDENCE_IMAGE') then 100 else 85 end;
  end if;

  return jsonb_build_object(
    'classification',v_classification,'raw_input_id',p_raw_input_id,'parser_version','line_candidate_v1','confidence',v_conf,
    'missing_fields',v_missing,'dedupe_rule','NAME_PHONE_DOB','dedupe_key',v_dedupe_key,
    'candidate',jsonb_strip_nulls(jsonb_build_object('full_name',ops.normalize_candidate_full_name(v_name),'phone',v_phone,'date_of_birth',v_dob,'age',v_age,'education',v_education,'weight_kg',v_weight,'height_cm',v_height,'origin_area',v_origin,'tattoo_outside_clothing',v_tattoo,'preferred_job','Next Can','job_id',v_job_id,'partner_id',v_partner_id,'source_type','Sourcing Partner','status','SCREENING')),
    'job_id',v_job_id,'partner_id',v_partner_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION ops.parse_line_candidate_raw_v1(p_raw_input_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v jsonb;
  v_raw ops.raw_inputs;
  v_text text;
  v_line text;
  v_name text;
  v_education text;
  v_m text[];
  v_missing jsonb;
  v_new_missing jsonb := '[]'::jsonb;
  x jsonb;
  v_origin text;
  v_phone text;
  v_dob text;
  v_dedupe text;
begin
  v:=ops.parse_line_candidate_raw_base_v1(p_raw_input_id);
  if v->>'classification'<>'CANDIDATE_LEAD' then
    return jsonb_set(v,'{parser_version}',to_jsonb('line_candidate_v1.2'::text),true);
  end if;

  select * into v_raw from ops.raw_inputs where raw_input_id=p_raw_input_id;
  if not found then return v; end if;
  v_text:=replace(coalesce(v_raw.raw_summary,''),E'\r','');

  foreach v_line in array regexp_split_to_array(v_text,E'\n') loop
    v_line:=btrim(v_line);
    if v_line='' then continue; end if;

    if v_name is null then
      if v_line ~* '^ๅ?(ชื่อ[- ]?นามสกุล|ชื่อนามสกุล|ชื่อ)[[:space:]]*[:：.-]?' then
        v_name:=ops.normalize_candidate_full_name(v_line);
        if v_name ~* '^(โรงงาน|จังหวัด|อำเภอ|ผู้แนะนำ|ผุ้แนะนำ|ผุแนะนำ|สายรถ|ซับ|อบรม)([[:space:]]|$)' then
          v_name:=null;
        end if;
      elsif v_line ~ '[ก-๙]+[[:space:]]+[ก-๙]+'
        and v_line !~ 'สมัคร|เน็กซ์|วุฒิ|วุติ|น้ำหนัก|นํ้าหนัก|ส่วนสูง|สูง|อายุ|เบอร์|โทร|รอยสัก|ลอยสัก|มาจาก|วันเดือนปีเกิด|ผู้แนะนำ|ผุ้แนะนำ|ผุแนะนำ|สายรถ|โรงงาน|จังหวัด|อำเภอ|ซับ|อบรม'
      then
        v_name:=ops.normalize_candidate_full_name(v_line);
      end if;
    end if;
  end loop;

  if v_name is null then
    v_m:=regexp_match(v_text,'^([ก-๙]+[[:space:]]+[ก-๙]+)[[:space:]]+(โรงงาน|สมัคร)','i');
    if v_m is not null then v_name:=ops.normalize_candidate_full_name(v_m[1]); end if;
  end if;

  v_m:=regexp_match(
    v_text,
    '(^|[\n])[[:space:]]*(วุฒิการศึกษา|วุฒิ|วุติ)[[:space:]]*[:：-]?[[:space:]]*(ม[.]?[[:space:]]*[36]|มอ6|ปวช[.]?[[:space:]]*3?|ปวส[.]?|ป[.]?[[:space:]]*ตรี|ปตรี|ปริญญาตรี|มัธยมศึกษาปีที่6|มัธยมศึกษาตอนปลาย|กศน[.]?[[:space:]]*ม[.]?6)',
    'i'
  );
  if v_m is null then
    v_m:=regexp_match(
      v_text,
      '[[:space:]](วุฒิการศึกษา|วุฒิ|วุติ)[[:space:]]*[:：-]?[[:space:]]*(ม[.]?[[:space:]]*[36]|มอ6|ปวช[.]?[[:space:]]*3?|ปวส[.]?|ป[.]?[[:space:]]*ตรี|ปตรี|ปริญญาตรี|มัธยมศึกษาปีที่6|มัธยมศึกษาตอนปลาย|กศน[.]?[[:space:]]*ม[.]?6)',
      'i'
    );
    if v_m is not null then
      v_education:=v_m[2];
    end if;
  else
    v_education:=v_m[3];
  end if;

  if v_education is not null then
    v_education:=regexp_replace(btrim(v_education),'[[:space:]]+','','g');
    v_education:=case
      when v_education ~* '^ม[.]?3$' then 'ม.3'
      when v_education ~* '^(ม[.]?6|มอ6|มัธยมศึกษาปีที่6|มัธยมศึกษาตอนปลาย)$' then 'ม.6'
      when v_education ~* '^ปวช[.]?3$' then 'ปวช.3'
      when v_education ~* '^ปวช[.]?$' then 'ปวช.'
      when v_education ~* '^ปวส[.]?$' then 'ปวส.'
      when v_education ~* '^(ป[.]?ตรี|ปตรี|ปริญญาตรี)$' then 'ป.ตรี'
      when v_education ~* '^กศน[.]?ม[.]?6$' then 'ม.6 กศน.'
      else v_education
    end;
  end if;

  if v_name is not null then
    v:=jsonb_set(v,'{candidate,full_name}',to_jsonb(v_name),true);
  end if;
  if v_education is not null then
    v:=jsonb_set(v,'{candidate,education}',to_jsonb(v_education),true);
  end if;

  v_missing:=coalesce(v->'missing_fields','[]'::jsonb);
  for x in select value from jsonb_array_elements(v_missing) loop
    if not (
      (x#>>'{}'='full_name' and v_name is not null)
      or (x#>>'{}'='education' and v_education is not null)
    ) then
      v_new_missing:=v_new_missing||jsonb_build_array(x);
    end if;
  end loop;
  v:=jsonb_set(v,'{missing_fields}',v_new_missing,true);

  v_phone:=nullif(v#>>'{candidate,phone}','');
  v_dob:=nullif(v#>>'{candidate,date_of_birth}','');
  if v_name is not null and v_phone is not null then
    v_dedupe:=encode(
      extensions.digest(
        lower(regexp_replace(v_name,'[[:space:]]+','','g'))||'|'||v_phone||'|'||coalesce(v_dob,''),
        'sha256'
      ),
      'hex'
    );
    v:=jsonb_set(v,'{dedupe_key}',to_jsonb(v_dedupe),true);
  end if;

  v_origin:=nullif(v#>>'{candidate,origin_area}','');
  if v_name is not null and v_phone is not null and v_education is not null then
    v:=jsonb_set(v,'{confidence}',to_jsonb(case when v_origin is null then 96 else 98 end),true);
  end if;

  v:=jsonb_set(v,'{parser_version}',to_jsonb('line_candidate_v1.2'::text),true);
  return v;
end;
$function$

CREATE OR REPLACE FUNCTION ops.run_line_candidate_ingestion_tick(p_now timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 100, p_actor text DEFAULT 'db_scheduler'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r record;
  v_route jsonb;
  v_parse jsonb;
  v_payload jsonb;
  v_cmd jsonb;
  v_finish jsonb;
  v_candidate jsonb;
  v_routed int:=0;
  v_candidate_events int:=0;
  v_commands int:=0;
  v_reconciled_commands int:=0;
  v_errors int:=0;
begin
  if p_limit<1 or p_limit>200 then raise exception 'limit must be between 1 and 200'; end if;
  perform ops.record_worker_heartbeat('candidate_intake','db_scheduler','test','HEALTHY','line-ingestion-v1.2',jsonb_build_object('actor',p_actor),p_now);

  for r in
    select e.event_pk from ops.events e
    where e.event_type='channel.raw.received' and e.source_system='LINE'
      and not exists(select 1 from ops.event_effects ee where ee.effect_key='line_ingestion_classification|'||e.raw_input_id)
    order by e.received_at,e.created_at limit p_limit
  loop
    begin
      v_route:=ops.route_line_raw_event_v1(r.event_pk);
      v_routed:=v_routed+1;
      if v_route->>'classification'='CANDIDATE_LEAD' then v_candidate_events:=v_candidate_events+1; end if;
    exception when others then v_errors:=v_errors+1;
    end;
  end loop;

  for r in select * from ops.claim_events('candidate_intake','db_scheduler',p_limit,120,p_now)
  loop
    begin
      if r.event_id like 'DERIVED:CANDIDATE_RECONCILIATION:%' then
        v_payload:=ops.build_candidate_reconciliation_payload_v1(r.raw_input_id);
        v_cmd:=ops.prepare_domain_command(r.event_pk,'candidate_intake',r.lease_token,v_payload,'Candidate',null);
        v_finish:=ops.finish_event_success(
          r.worker_run_pk,r.lease_token,'candidate_reconciliation_proposal_prepared','candidate_reconciliation_proposal|'||r.raw_input_id,
          'CandidateLead',null,'ops.domain_commands:'||(v_cmd->>'command_pk'),
          jsonb_build_object('raw_input_id',r.raw_input_id,'command_pk',v_cmd->>'command_pk','validation_status',v_cmd->>'validation_status','master_apply_deferred_to','GOOGLE_SHEETS_DRIVE','reconciliation',true),p_now
        );
        update ops.raw_inputs
        set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
          'candidate_command_pk',v_cmd->>'command_pk',
          'candidate_command_validation',v_cmd->>'validation_status',
          'candidate_worker_completed_at',p_now,
          'candidate_reconciliation_command_ready',true
        ),updated_at=now()
        where raw_input_id=r.raw_input_id;
        v_commands:=v_commands+1;
        v_reconciled_commands:=v_reconciled_commands+1;
        continue;
      end if;

      v_parse:=ops.parse_line_candidate_raw_v1(r.raw_input_id);
      if v_parse->>'classification'<>'CANDIDATE_LEAD' then
        perform ops.finish_event_failure(r.worker_run_pk,r.lease_token,'VALIDATION','Derived candidate event no longer parses as candidate',jsonb_build_object('raw_input_id',r.raw_input_id),p_now);
        v_errors:=v_errors+1;
        continue;
      end if;
      v_candidate:=coalesce(v_parse->'candidate','{}'::jsonb)||jsonb_build_object('status','SCREENING');
      if nullif(v_parse->>'partner_id','') is not null then v_candidate:=v_candidate||jsonb_build_object('source_type','Sourcing Partner'); end if;
      v_payload:=jsonb_build_object(
        'candidate',v_candidate,
        'private_contact',jsonb_build_object('full_name',v_parse#>>'{candidate,full_name}','phone',v_parse#>>'{candidate,phone}','date_of_birth',v_parse#>>'{candidate,date_of_birth}'),
        'partner_id',v_parse->>'partner_id','job_id',v_parse->>'job_id','dedupe_rule','NAME_PHONE_DOB','dedupe_key',v_parse->>'dedupe_key',
        'ai_confidence',v_parse->'confidence','missing_fields',v_parse->'missing_fields','parser_version','line_candidate_v1','source_raw_input_id',r.raw_input_id,
        'operational_master_target','GOOGLE_SHEETS_DRIVE','auto_submit',false
      );
      v_cmd:=ops.prepare_domain_command(r.event_pk,'candidate_intake',r.lease_token,v_payload,'Candidate',null);
      v_finish:=ops.finish_event_success(r.worker_run_pk,r.lease_token,'candidate_proposal_prepared','candidate_proposal|'||r.raw_input_id,'CandidateLead',null,'ops.domain_commands:'||(v_cmd->>'command_pk'),jsonb_build_object('raw_input_id',r.raw_input_id,'command_pk',v_cmd->>'command_pk','validation_status',v_cmd->>'validation_status','master_apply_deferred_to','GOOGLE_SHEETS_DRIVE'),p_now);
      update ops.raw_inputs set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('candidate_command_pk',v_cmd->>'command_pk','candidate_command_validation',v_cmd->>'validation_status','candidate_worker_completed_at',p_now),updated_at=now() where raw_input_id=r.raw_input_id;
      v_commands:=v_commands+1;
    exception when others then
      begin perform ops.finish_event_failure(r.worker_run_pk,r.lease_token,'VALIDATION',sqlerrm,jsonb_build_object('raw_input_id',r.raw_input_id),p_now); exception when others then null; end;
      v_errors:=v_errors+1;
    end;
  end loop;

  return jsonb_build_object('routed_raw_events',v_routed,'candidate_events_created',v_candidate_events,'candidate_commands_prepared',v_commands,'reconciled_commands_prepared',v_reconciled_commands,'errors',v_errors,'actor',p_actor,'ran_at',p_now);
end;
$function$

CREATE OR REPLACE FUNCTION ops.scheduler_tick(p_now timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 100, p_trigger_source text DEFAULT 'MANUAL'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_retry_created integer;
  v_result jsonb;
  v_ingest jsonb;
begin
  v_retry_created := ops.sync_retry_schedules(p_now, p_limit);
  v_result := ops.run_due_schedules(p_now, p_limit, p_trigger_source);
  update ops.scheduler_runs set retry_schedules_created=v_retry_created where scheduler_run_pk=(v_result->>'scheduler_run_pk')::uuid;
  begin
    v_ingest:=ops.run_line_candidate_ingestion_tick(p_now,least(p_limit,200),'scheduler_tick');
  exception when others then
    v_ingest:=jsonb_build_object('errors',1,'scheduler_error',left(sqlerrm,500));
  end;
  return v_result||jsonb_build_object('retry_schedules_created',v_retry_created,'line_candidate_ingestion',v_ingest);
end;
$function$
